import { l, type L, type Class10Chapter, type VisualScene, type ChapterVisual } from './types';
import type { ChoiceTask, SelectTask, MatchTask, NumberTask, OrderTask } from '../lesson-content';

type Option = [string, L, L];
const base = (prompt: L, context: L) => ({
  prompt, context,
  success: l('Your conclusion fits these supplied records. Keep the remaining uncertainty in your evidence note.', 'आपका निष्कर्ष दिए रिकॉर्ड से मेल खाता है। बची अनिश्चितता अपने प्रमाण नोट में रखें।'),
  correction: l('Compare your submitted work with the case-specific reasons below, then revise the affected part.', 'अपने दिए काम को नीचे मामले के खास कारणों से मिलाएँ, फिर संबंधित हिस्सा सुधारें।'),
  hint: l('Name the exact source, what it establishes and what it leaves unanswered. Ask for adult support through a known route.', 'ठीक स्रोत, उससे पता चलने वाली बात और बाकी सवाल लिखें। ज्ञात रास्ते से बड़े की मदद लें।'),
});
const choice = (p:L,c:L,options:Option[],correct:string):ChoiceTask => ({...base(p,c),kind:'choice',options:options.map(([id,label,feedback])=>({id,label,feedback})),correct});
const select = (p:L,c:L,items:Option[],expected:string[]):SelectTask => ({...base(p,c),kind:'select',items:items.map(([id,label,feedback])=>({id,label,feedback})),expected});
const match = (p:L,c:L,rows:[string,L,string,L][],options:[string,L][]):MatchTask => ({...base(p,c),kind:'match',rows:rows.map(([id,label,answer,explanation])=>({id,label,answer,explanation})),options:options.map(([id,label])=>({id,label}))});
const number = (p:L,c:L,fields:[string,L,number,L][]):NumberTask => ({...base(p,c),kind:'number',fields:fields.map(([id,label,answer,explanation])=>({id,label,answer,explanation,min:0}))});
const order = (p:L,c:L,steps:[string,L,L][],dependencies:[string,string,L][]):OrderTask => ({...base(p,c),kind:'order',items:steps.map(([id,label])=>({id,label})),expected:steps.map(([id])=>id),stepReasons:steps.map(([, ,reason])=>reason),prerequisites:dependencies.map(([before,after,reason])=>({before,after,reason}))});
const scene = (title:L,caption:L,dialogue:L) => ({title,caption,dialogue});

// Frames are authored case states, not a generated story sequence. Moving a card
// places its claim beside a source, into a status lane, or outside a disclosure lane.
type Frame = [string, number, number, L, ('active'|'warning'|'complete')?, string[]?];
const visual = (layout:ChapterVisual['layout'], nodes:[string,L,L][], plans:[Frame,Frame,Frame][], variants:[string,L,number,number][], prompt:L):ChapterVisual => {
  const positions = [[18,25],[50,25],[82,25],[18,72],[50,72],[82,72],[50,85]];
  const authoredNodes = nodes.map(([id,label,value],i)=>({id,label,value,x:positions[i][0],y:positions[i][1],shape:'card' as const}));
  // Relationships are authored for the help case; the other diagrams compare cards
  // without asserting an unverified relationship between them.
  const help = nodes[0][0] === 'incident';
  const edges = help ? [
    {id:'adult-provider',from:'adult',to:'provider'},
    {id:'adult-official',from:'adult',to:'official'},
    {id:'facts-provider',from:'private',to:'provider'},
    {id:'facts-official',from:'private',to:'official'},
  ] : [];
  const scenes = plans.map((frames, sceneIndex)=>({steps:frames.map(([, , ,value, ,hidden=[]], stepIndex)=>{
    // Each step is a self-contained snapshot. Carry earlier changes within this
    // scene into the current snapshot because the resolver starts at the base.
    const values:Record<string,L> = {};
    const moves: {id:string;x:number;y:number}[] = [];
    const states:Record<string,'active'|'warning'|'complete'> = {};
    for (const [prior,px,py,pvalue,pstatus='active'] of frames.slice(0,stepIndex+1)) {
      values[prior]=pvalue; states[prior]=pstatus;
      const old=moves.findIndex(m=>m.id===prior); if(old>=0) moves.splice(old,1);
      moves.push({id:prior,x:px,y:py});
    }
    const set=(node:string,v:L,state:'active'|'warning'|'complete',mx?:number,my?:number)=>{
      values[node]=v; states[node]=state;
      if(mx!==undefined && my!==undefined){const old=moves.findIndex(m=>m.id===node);if(old>=0)moves.splice(old,1);moves.push({id:node,x:mx,y:my});}
    };
    const first=nodes[0][0];
    if(first==='source' && sceneIndex===1 && stepIndex===2)
      set('copy',l('Maple Room; registration link added','मेपल रूम; पंजीकरण लिंक जुड़ा'),'warning',65,40);
    if(first==='voice' && sceneIndex>=4 && stepIndex===2)
      set('note',l('Request contradicted; voice technology unknown','माँग खंडित; आवाज़ की तकनीक अज्ञात'),'complete',82,72);
    if(first==='image' && sceneIndex===1 && stepIndex===2)
      set('pending',l('B22 ₹750 pending; completion time unknown','B22 ₹750 लंबित; पूरा होने का समय अज्ञात'),'warning',65,60);
    if(first==='image' && sceneIndex===2 && stepIndex===2)
      set('image',l('B22 ₹750 success claim; reference matches','B22 ₹750 सफलता दावा; संदर्भ मिलता है'),'active',60,45);
    if(first==='image' && sceneIndex===4 && stepIndex===2)
      set('reversed',l('B23: ₹320 credit − ₹320 reversal = ₹0','B23: ₹320 जमा − ₹320 उलटाव = ₹0'),'complete',75,65);
    if(first==='screen' && sceneIndex===0 && stepIndex===2)
      set('screen',l('₹8000 → ₹12500; display increase ₹4500','₹8000 → ₹12500; स्क्रीन बढ़ोतरी ₹4500'),'active',65,40);
    if(first==='screen' && sceneIndex===2 && stepIndex===2)
      set('fee',l('Further ₹600 demanded; no incoming proof','और ₹600 माँगे; आने का प्रमाण नहीं'),'warning',35,60);
    if(first==='call' && sceneIndex===4 && stepIndex===2)
      set('official',l('Teacher uses verified route; caller permission not needed','टीचर पुष्ट रास्ता लेते हैं; कॉल की अनुमति ज़रूरी नहीं'),'complete',50,45);
    if(first==='source' && sceneIndex===2){
      set('copy',l('Maple Room; registration link added','मेपल रूम; पंजीकरण लिंक जुड़ा'),'warning',65,40);
    }
    if(first==='source' && sceneIndex>=4 && stepIndex===2){
      set('venue',l('Cedar Hall confirmed; Maple Room contradicted','सीडर हॉल पुष्ट; मेपल रूम खंडित'),'complete',40,40);
      set('office',l('Cedar Hall; practice date unchanged','सीडर हॉल; अभ्यास तारीख अपरिवर्तित'),'complete',50,55);
      set('link',l('Link author unresolved','लिंक रचयिता अनसुलझा'),'warning',72,60);
    }
    if(first==='voice' && sceneIndex>=4 && stepIndex===2){
      set('known',l('Cousin denies making the request','भाई माँग करने से मना करता है'),'complete',50,45);
      set('voice',l('Voice production still unknown','आवाज़ बनने का तरीका अभी अज्ञात'),'warning',75,45);
    }
    if(first==='price' && sceneIndex===2 && stepIndex===2)
      set('pouch',l('Pouch selected: ₹90','थैली चुनी: ₹90'),'warning',45,60);
    if(first==='price' && (sceneIndex===4 && stepIndex===2 || sceneIndex===5 && stepIndex>=1)){
      set('pouch',l('Pouch removed; ₹90 excluded','थैली हटी; ₹90 बाहर'),'complete',18,80);
      set('total',l('Without pouch: ₹870 − ₹90 = ₹780','थैली बिना: ₹870 − ₹90 = ₹780'),'complete',50,55);
    }
    if(first==='screen' && sceneIndex===4 && stepIndex===2){
      set('screen',l('Display column: ₹12500','स्क्रीन खाना: ₹12500'),'active',30,40);
      set('provider',l('Confirmed received column: ₹0','पुष्ट प्राप्त खाना: ₹0'),'complete',65,55);
    }
    if(help && sceneIndex>=3 && sceneIndex<=4 && stepIndex===2){
      set('private',l('F46; ₹1200; 09:20; access exposed','F46; ₹1200; 09:20; पहुँच खुली'),'complete',50,50);
      set('seller',l('Seller excluded; no secrets or unrelated photo','विक्रेता बाहर; रहस्य और असंबंधित तस्वीर नहीं'),'warning',82,80);
    }
    const activeEdges = help && sceneIndex===2 ? (stepIndex===0?['adult-provider']:stepIndex===1?['adult-official']:['adult-provider','adult-official'])
      : help && sceneIndex===4 ? (stepIndex===0?['facts-provider']:stepIndex===1?['facts-provider','facts-official']:[]) : [];
    return {label:value,description:value,active:Object.keys(states).filter(n=>states[n]==='active'&&!hidden.includes(n)),
      ...(hidden.length?{hidden}:{}),warning:Object.keys(states).filter(n=>states[n]==='warning'&&!hidden.includes(n)),
      complete:Object.keys(states).filter(n=>states[n]==='complete'&&!hidden.includes(n)),moves,values,activeEdges};
  })}));
  return {layout,nodes:authoredNodes,edges,
    scenes:scenes as [VisualScene,VisualScene,VisualScene,VisualScene,VisualScene,VisualScene],
    exploration:{title:l('Inspect the supplied variants','दिए रूपों की जाँच करें'),prompt,variants:variants.map(([id,label,scene,step])=>({id,label,scene,step}))}};
};
const common = {
  strand:'Cyber Fraud' as const,
  familyAction:l('Use the invented Decision Lab cards to explain one verification plan at home. Keep real accounts, payment apps and private messages closed.', 'घर पर काल्पनिक डिसीजन लैब कार्ड से एक जाँच योजना समझाएँ। असली खाते, भुगतान ऐप और निजी संदेश बंद रखें।'),
  reflection:l('Which record supports your conclusion, and which question remains open? Explain the next supported action without blaming the person who asked for help.', 'कौन सा रिकॉर्ड आपके निष्कर्ष का आधार है और कौन सा सवाल बाकी है? मदद माँगने वाले को दोष दिए बिना प्रमाण पर आधारित अगला कदम समझाएँ।'),
  teacherPrompt:l('Ask learners to cite a supplied record, explain a rejected action and revise their conclusion when that record changes. Support private help without blame.', 'बच्चों से दिया रिकॉर्ड दिखाने, छोड़ी कार्रवाई समझाने और रिकॉर्ड बदलने पर निष्कर्ष सुधारने को कहें। बिना दोष दिए निजी मदद दें।'),
  rubric:[l('Distinguishes a claim, a supported fact and an unresolved question.','दावा, प्रमाणित तथ्य और बाकी सवाल अलग करता है।'),l('Uses the specific source or calculation to justify the decision.','फैसले के लिए खास स्रोत या गणना का कारण देता है।'),l('Prepares a minimal private record and an independent, adult-supported next step.','न्यूनतम निजी रिकॉर्ड और बड़े की मदद से स्वतंत्र अगला कदम बनाता है।')] as [L,L,L],
};

